var a={en:`Two workers may edit the same inspection. Photos exceed 50 MB and connectivity interrupts uploads. Supervisors need conflict history.`,ua:`Двоє працівників можуть редагувати одну інспекцію. Фото понад 50 МБ, мережа перериває передачу. Керівнику потрібна історія конфліктів.`};var c={en:[`Add record version/ETag and supervisor conflict review.`,`Define chunk IDs, checksums and resumable upload.`,`Show local pending, server accepted and conflict states.`],ua:[`Додай версії/ETag і розгляд конфлікту керівником.`,`Визнач ID частин, checksum та відновлювану передачу.`,`Покажи локальне очікування, прийняття сервером і конфлікт.`]};var t=[{en:`A conflicting update cannot silently overwrite another worker.`,ua:`Конфлікт не може непомітно перезаписати іншу зміну.`},{en:`Retrying a chunk does not duplicate an attachment.`,ua:`Повтор частини файлу не дублює вкладення.`}];var o={scenario:a,tasks:c,checks:t};export{t as checks,o as default,a as scenario,c as tasks};